import { observer } from 'mobx-react';
import { createObject, setSelectedAsset, cleanupScene } from './CreateObjectModel';

const CreateObjectView = observer(({ model }) => {
  const [assetValue, setAssetValue] = useState('');

  const handleAssetChange = e => {
    setAssetValue(e.target.value);
  };

  const handleCreateObjectClick = () => {
    createObject(assetValue).then(() => {
      setSelectedAsset(assetValue);
    });
  };

  const handleCleanupSceneClick = () => {
    cleanupScene();
  };

