To tackle this challenge, we can create a dictionary of commonly misused homophones and their correct equivalents. Here's how you could implement such a solution in Swift:

```swift
let homophoneDictionary: [String: String] = [
    "there": "they're",
    "their": "there",
    "they're": "their"
]

func replaceHomophones(_ sentence: String) -> String {
    let words = sentence.components(separatedBy: .whitespacesAndNewlines)
    var correctedSentence = ""

    for word in words {
        // Check if current word is a key in our dictionary
        guard let replacement = homophoneDictionary[word], !words.prefix(words.firstIndex(of: word)!).contains(replacement) else {
            correctedSentence += "\(word) "
            continue
        }

        // If word is followed by a space, we need to add it back after replacing
        let nextWord = words[words.firstIndex(of: word)! + 1]
        let space = nextWord.prefix(1) == " " ? " " : ""

        correctedSentence += "\(replacement)\(space)"
    }

    return correctedSentence
}

