```python
def lcs(str1, str2):
    m = len(str1)
    n = len(str2)
    tab = [[None] * (n+1) for _ in range(m+1)]

    # Filling the bottom row and left column of the table
    for I in range(m+1):
        tab[i][0] = 0

    for j in range(n+1):
        tab[0][j] = 0

    for I in range(1, m+1):
        for j in range(1, n+1):
            if str1[i-1] == str2[j-1]:
                tab[i][j] = tab[i-1][j-1] + 1
            else:
                tab[i][j] = max(tab[i-1][j], tab[i][j-1])

    i, j = m, n
    lcs_str = ""

    while I > 0 and j > 0:
        if str1[i-1] == str2[j-1]:
            lcs_str = str1[i-1] + lcs_str
            I -= 1
            j -= 1
        elif tab[i-1][j] > tab[i][j-1]:
            I -= 1
        else:
            j -= 1

    return lcs_str[::-1]

